package dev.rahul.booking;


import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static dev.rahul.booking.CommerceModels.*;
import static dev.rahul.booking.CatalogService.*;
@Service
public class CommerceService {
 private final JdbcClient db;private final CatalogService catalog;private final BookingService bookings;private final ParticipantService participants;private final LedgerService ledger;private final BusinessService business;private final Commands commands;
 public CommerceService(JdbcClient db,CatalogService catalog,BookingService bookings,ParticipantService participants,LedgerService ledger,BusinessService business,Commands commands){this.db=db;this.catalog=catalog;this.bookings=bookings;this.participants=participants;this.ledger=ledger;this.business=business;this.commands=commands;}
 public PaymentSettings settings(Actor a,UUID provider){catalog.provider(a,provider);return db.sql("SELECT cash_enabled,wallet_enabled FROM provider_payment_settings WHERE tenant_id=:tenant AND provider_id=:provider").param("tenant",a.tenantId()).param("provider",provider).query((rs,n)->new PaymentSettings(rs.getBoolean(1),rs.getBoolean(2))).optional().orElse(new PaymentSettings(false,false));}
 @Transactional public PaymentSettings configure(Actor a,UUID provider,PaymentSettings r){a.requireAdmin();catalog.lockProvider(a,provider);db.sql("INSERT INTO provider_payment_settings(provider_id,tenant_id,cash_enabled,wallet_enabled) VALUES(:provider,:tenant,:cash,:wallet) ON CONFLICT(provider_id) DO UPDATE SET cash_enabled=excluded.cash_enabled,wallet_enabled=excluded.wallet_enabled").param("provider",provider).param("tenant",a.tenantId()).param("cash",r.cashPayEnabled()).param("wallet",r.walletPayEnabled()).update();return r;}
 @Transactional public Models.Service price(Actor a,UUID service,Pricing r){a.requireAdmin();LedgerService.currency(r.currency());if(db.sql("UPDATE services SET price_minor=:price,currency=:currency WHERE tenant_id=:tenant AND id=:id").param("price",r.priceMinor()).param("currency",r.currency()).param("tenant",a.tenantId()).param("id",service).update()==0)throw ApiFailure.notFound();return catalog.service(a,service);}
 public Quote quote(Actor a,Checkout r){UUID provider=null,payer=null;String currency=null;long total=0;var amounts=new ArrayList<Long>();
  for(var line:r.bookings()){
   var student=participants.resolve(a,line.participantId());UUID effectivePayer=participants.payer(student);var service=catalog.service(a,line.serviceId());catalog.provider(a,line.providerId());business.requireServiceAllowed(a,line.providerId(),line.serviceId());business.validateStart(a,line.startsAt());if(line.roomId()!=null)business.room(a,line.roomId());bookings.fits(a,line.providerId(),line.startsAt(),line.startsAt().plus(java.time.Duration.ofMinutes(service.durationMinutes())));
   if(provider!=null&&(!provider.equals(line.providerId())||!payer.equals(effectivePayer)||!currency.equals(service.currency())))throw ApiFailure.invalid("A checkout must use one provider, payer and currency");provider=line.providerId();payer=effectivePayer;currency=service.currency();total=Math.addExact(total,service.priceMinor());if(total>1000000000000L)throw ApiFailure.invalid("Checkout total exceeds the supported range");amounts.add(service.priceMinor());
  }
  var methods=new ArrayList<String>();var settings=settings(a,provider);if(settings.cashPayEnabled())methods.add("CASH");if(settings.walletPayEnabled())methods.add("WALLET");if(settings.cashPayEnabled()&&settings.walletPayEnabled())methods.add("WALLET_CASH");return new Quote(payer,provider,currency,total,ledger.balance(a,payer,provider,currency).balanceMinor(),amounts,methods);
 }
 @Transactional public Order checkout(Actor a,Checkout r,String key){var replay=commands.find(a,"CHECKOUT",key,r);if(replay.isPresent())return order(a,replay.get().getFirst());UUID provider=r.bookings().getFirst().providerId();catalog.lockProvider(a,provider);var q=quote(a,r);if((r.expectedTotalMinor()!=null&&r.expectedTotalMinor()!=q.totalMinor())||(r.expectedCurrency()!=null&&!r.expectedCurrency().equals(q.currency())))throw ApiFailure.conflict("Price changed; review a fresh quote before paying");if(!q.allowedMethods().contains(r.paymentMethod()))throw ApiFailure.conflict("Payment method is not enabled for this provider");
  long walletUse=switch(r.paymentMethod()){case "WALLET"->q.totalMinor();case "WALLET_CASH"->Math.min(q.availableWalletMinor(),q.totalMinor());default->0;};
  UUID order=UUID.randomUUID();if(walletUse>0)ledger.move(a,q.payerId(),q.providerId(),q.currency(),walletUse,false,"CHECKOUT_DEBIT","Wallet payment for booking checkout",order);
  db.sql("INSERT INTO commerce_orders(id,tenant_id,provider_id,customer_id,booked_by,currency,payment_method) VALUES(:id,:tenant,:provider,:payer,:actor,:currency,:method)").param("id",order).param("tenant",a.tenantId()).param("provider",provider).param("payer",q.payerId()).param("actor",a.userId()).param("currency",q.currency()).param("method",r.paymentMethod()).update();
  long remaining=walletUse;for(int i=0;i<r.bookings().size();i++){var b=bookings.create(a,r.bookings().get(i),"checkout-"+SessionService.hash(key)+":"+i);long amount=q.lineAmountsMinor().get(i),paid=Math.min(remaining,amount);remaining-=paid;db.sql("INSERT INTO commerce_order_items(booking_id,tenant_id,order_id,amount_minor,wallet_paid_minor,cash_due_minor) VALUES(:booking,:tenant,:order,:amount,:wallet,:cash)").param("booking",b.id()).param("tenant",a.tenantId()).param("order",order).param("amount",amount).param("wallet",paid).param("cash",amount-paid).update();}
  commands.save(a,"CHECKOUT",key,r,List.of(order));return order(a,order);
 }
 private static final String ORDER_ACCESS="o.tenant_id=:tenant AND (:admin OR o.customer_id=:user OR o.booked_by=:user OR EXISTS(SELECT 1 FROM providers p WHERE p.tenant_id=o.tenant_id AND p.id=o.provider_id AND p.user_id=:user))";
 record Header(UUID id,UUID payer,UUID actor,UUID provider,String currency,String method){}
 public Order order(Actor a,UUID id){var h=db.sql("SELECT o.* FROM commerce_orders o WHERE "+ORDER_ACCESS+" AND o.id=:id").param("tenant",a.tenantId()).param("admin",a.admin()).param("user",a.userId()).param("id",id).query((rs,n)->new Header(rs.getObject("id",UUID.class),rs.getObject("customer_id",UUID.class),rs.getObject("booked_by",UUID.class),rs.getObject("provider_id",UUID.class),rs.getString("currency"),rs.getString("payment_method"))).optional().orElseThrow(ApiFailure::notFound);
  var items=db.sql("SELECT * FROM commerce_order_items WHERE tenant_id=:tenant AND order_id=:id ORDER BY booking_id").param("tenant",a.tenantId()).param("id",id).query((rs,n)->new OrderItem(rs.getObject("booking_id",UUID.class),rs.getLong("amount_minor"),rs.getLong("wallet_paid_minor"),rs.getLong("cash_due_minor"),rs.getLong("cash_collected_minor"),rs.getLong("refunded_minor"),rs.getTimestamp("cancelled_at")!=null)).list();long total=items.stream().mapToLong(OrderItem::amountMinor).sum(),wallet=items.stream().mapToLong(OrderItem::walletPaidMinor).sum(),cash=items.stream().mapToLong(OrderItem::cashDueMinor).sum(),collected=items.stream().mapToLong(OrderItem::cashCollectedMinor).sum(),refunded=items.stream().mapToLong(OrderItem::refundedMinor).sum();var active=items.stream().filter(i->!i.cancelled()).toList();long outstanding=active.stream().mapToLong(i->i.cashDueMinor()-i.cashCollectedMinor()).sum();String status=active.isEmpty()?"CANCELLED":outstanding==0?"PAID":active.stream().mapToLong(i->i.walletPaidMinor()+i.cashCollectedMinor()).sum()>0?"PARTIALLY_PAID":"UNPAID";return new Order(h.id(),h.payer(),h.actor(),h.provider(),h.currency(),h.method(),status,total,wallet,cash,collected,refunded,items);
 }
 public Models.Page<Order> orders(Actor a,int page,int size){bounds(page,size);var ids=db.sql("SELECT o.id FROM commerce_orders o WHERE "+ORDER_ACCESS+" ORDER BY o.created_at DESC,o.id DESC LIMIT :limit OFFSET :offset").param("tenant",a.tenantId()).param("admin",a.admin()).param("user",a.userId()).param("limit",size+1).param("offset",page*size).query(UUID.class).list();return new Models.Page<>(ids.stream().limit(size).map(id->order(a,id)).toList(),page,size,ids.size()>size);}
 @Transactional public Order receipt(Actor a,UUID booking,CashReceipt r,String key){var replay=commands.find(a,"CASH_RECEIPT:"+booking,key,r);UUID provider=bookings.get(a,booking).providerId();business.requireProviderManager(a,provider);catalog.lockProvider(a,provider);var line=db.sql("SELECT i.order_id,i.cash_due_minor-i.cash_collected_minor AS remaining,i.cancelled_at IS NOT NULL AS cancelled FROM commerce_order_items i WHERE i.tenant_id=:tenant AND i.booking_id=:booking FOR UPDATE").param("tenant",a.tenantId()).param("booking",booking).query((rs,n)->Map.of("order",rs.getObject(1,UUID.class),"remaining",rs.getLong(2),"cancelled",rs.getBoolean(3))).optional().orElseThrow(ApiFailure::notFound);UUID order=(UUID)line.get("order");if(replay.isPresent())return order(a,order);if((boolean)line.get("cancelled")||r.amountMinor()>(long)line.get("remaining"))throw ApiFailure.conflict("Receipt exceeds the outstanding cash amount or booking is cancelled");db.sql("UPDATE commerce_order_items SET cash_collected_minor=cash_collected_minor+:amount WHERE tenant_id=:tenant AND booking_id=:booking").param("amount",r.amountMinor()).param("tenant",a.tenantId()).param("booking",booking).update();UUID id=UUID.randomUUID();db.sql("INSERT INTO cash_receipts(id,tenant_id,booking_id,amount_minor,actor_id) VALUES(:id,:tenant,:booking,:amount,:actor)").param("id",id).param("tenant",a.tenantId()).param("booking",booking).param("amount",r.amountMinor()).param("actor",a.userId()).update();commands.save(a,"CASH_RECEIPT:"+booking,key,r,List.of(id));return order(a,order);}
}
